// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzzed parameter controls which callee we use: 0 => non-reverting helper, 1 => reverting helper
    function testFuzz_property(uint8 mode) public {
        // keep domain small but allow both values
        mode = uint8(bound(mode, 0, 1));

        // deploy helpers
        NonReverter nr = new NonReverter();
        Reverter rv = new Reverter();

        address callee = mode == 0 ? address(nr) : address(rv);

        // Call c.forward(...) and record whether it returns (ok) or reverts (caught as false)
        bool ok;
        try c.forward(callee, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion):
        // For the reference contract: calling forward with a callee that always reverts (mode==1)
        // must make forward revert (ok == false). The mutant that inverts the require will make
        // forward succeed instead for that callee; so this assertion passes on the reference for
        // all inputs and fails on the mutant for some input (mode==1).
        if (mode == 1) {
            // when callee reverts, reference should cause forward to revert => ok == false
            assertTrue(ok == false);
        } else {
            // when callee does NOT revert, reference should allow forward to succeed => ok == true
            assertTrue(ok == true);
        }
    }
}

// Helper that always reverts when called
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable { revert("revert"); }
}

// Helper that always succeeds (records nothing but accepts calls)
contract NonReverter {
    fallback() external payable { /* succeed silently */ }
    receive() external payable { /* succeed silently */ }
}
